return $input.all().map((item, i) => {
  const test = $('Test Messages').all()[i].json;
  const out = item.json.output;
  return {
    json: {
      id: test.id,
      message: test.message,
      expected_category: test.expected_category,
      got_category: out.category,
      category_ok: out.category === test.expected_category,
      expected_urgent: test.expected_urgent,
      got_urgent: out.urgent,
      urgent_ok: out.urgent === test.expected_urgent,
      confidence: out.confidence
    }
  };
});

const rows = $input.all().map(i => i.json);
const catOk = rows.filter(r => r.category_ok).length;
const urgOk = rows.filter(r => r.urgent_ok).length;

return [{
  json: {
    total: rows.length,
    category_accuracy: catOk + "/" + rows.length,
    urgent_accuracy: urgOk + "/" + rows.length
  }
}];
